    ];

    let menuItemIndex = $('#menu-items-container tr').length;
    let currentIconInput = null;

    // --- Icon Picker Logic ---
    const $modal = $('#icon-picker-modal');
    const $iconGrid = $('#icon-grid');
    const $iconSearch = $('#icon-search');

    function populateIconGrid(filter = '') {
        $iconGrid.empty();
        const searchTerm = filter.toLowerCase();
        const filteredIcons = faIcons.filter(icon => icon.text.toLowerCase().includes(searchTerm) || icon.value.toLowerCase().includes(searchTerm));
        
        $.each(filteredIcons, function(i, icon) {
            const iconItem = `
                <div class="icon-item" data-icon-class="${icon.value}" title="${icon.text} (${icon.value})">
                    <i class="${icon.value}"></i>
                    <span>${icon.text}</span>
                </div>
            `;
            $iconGrid.append(iconItem);
        });
    }

    // Initial population
    populateIconGrid();

    $iconSearch.on('input', function() {
        populateIconGrid($(this).val());
    });

    $(document).on('click', '.choose-icon', function() {
        currentIconInput = $(this).siblings('.icon-input');
        $modal.show();
        $iconSearch.focus();
    });

    $modal.on('click', '.modal-close, .icon-picker-modal-backdrop', function() {
        $modal.hide();
        currentIconInput = null;
    });

    $iconGrid.on('click', '.icon-item', function() {
        if (currentIconInput) {
            const iconClass = $(this).data('icon-class');
            currentIconInput.val(iconClass).trigger('input');
            $modal.hide();
            currentIconInput = null;
        }
    });
    // --- End Icon Picker Logic ---


    // --- Original Form Logic ---
    $("#add-menu-item").click(function() {
        const html = `
            <tr>
                <td><input type="text" name="menu_items[${menuItemIndex}][title]" class="regular-text" placeholder="عنوان منو"></td>
                <td><input type="url" name="menu_items[${menuItemIndex}][url]" class="regular-text" placeholder="https://example.com"></td>
                <td>
                    <div class="icon-input-wrapper">
                        <input type="text" name="menu_items[${menuItemIndex}][icon]" class="regular-text icon-input" placeholder="fa-solid fa-house">
                        <button type="button" class="button choose-icon">انتخاب</button>
                    </div>
                </td>
                <td><span class="icon-preview"></span></td>
                <td><button type="button" class="button button-secondary remove-menu-item">حذف</button></td>
            </tr>
        `;
        $("#menu-items-container").append(html);
        menuItemIndex++;
    });
    
    $(document).on("click", ".remove-menu-item", function() {
        $(this).closest("tr").remove();
    });
    
    $(document).on("input", ".icon-input", function() {
        const iconClass = $(this).val();
        $(this).closest("tr").find(".icon-preview").html('<i class="' + iconClass + '"></i>');
    });
    
    $("#menu-icons-form").on("submit", function(e) {
        e.preventDefault();
        
        let formData = $(this).serialize();
        
        $.ajax({
            url: ajaxurl,
            type: "POST",
            data: {
                action: 'save_menu_icons',
                nonce: $('#nonce').val(),
                menu_items: $(this).serialize()
            },
            success: function(response) {
                if (response.success) {
                    alert("تغییرات با موفقیت ذخیره شد!");
                    location.reload();
                } else {
                    alert("خطا در ذخیره سازی: " + response.data);
                }
            },
            error: function() {
                alert("خطا در ارتباط با سرور");
            }
        });
    });
});
