.icon-preview {
    font-size: 22px;
    color: #1d2327;
}
.icon-preview i {
    width: 25px;
    text-align: center;
}
#menu-items-container td {
    vertical-align: middle;
}
.postbox h2 {
    padding: 10px 15px;
    margin: 0;
}
.postbox .inside {
    padding: 15px;
}
.icon-input-wrapper {
    display: flex;
    align-items: center;
}
.icon-input-wrapper .icon-input {
    flex-grow: 1;
}
.icon-input-wrapper .choose-icon {
    margin-right: 8px;
}

/* Modal Styles */
.icon-picker-modal-wrapper {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 100000;
    display: flex;
    align-items: center;
    justify-content: center;
}
.icon-picker-modal-backdrop {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.6);
}
.icon-picker-modal-content {
    position: relative;
    background: #fdfdfd;
    width: 90%;
    max-width: 800px;
    max-height: 80vh;
    border-radius: 4px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    display: flex;
    flex-direction: column;
}
.modal-header {
    padding: 15px;
    border-bottom: 1px solid #ddd;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.modal-header h2 {
    margin: 0;
    font-size: 1.2em;
}
.modal-close {
    background: none;
    border: none;
    font-size: 24px;
    cursor: pointer;
    padding: 0 10px;
}
.modal-body {
    padding: 15px;
    overflow-y: auto;
}
#icon-search {
    width: 100%;
    padding: 8px;
    margin-bottom: 15px;
    border: 1px solid #ddd;
    border-radius: 4px;
}
.icon-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 10px;
}
.icon-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 10px;
    border: 1px solid #eee;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.2s, color 0.2s;
    text-align: center;
}
.icon-item:hover {
    background-color: #007cba;
    color: #fff;
    border-color: #007cba;
}
.icon-item i {
    font-size: 24px;
    margin-bottom: 8px;
}
.icon-item span {
    font-size: 12px;
    word-break: break-all;
}
</style>